$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$sourcePath='P:\projects\step124-gdn-native-source-r1.json'
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
function Verify-File([string]$Path,[string]$Sha){
 if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}
}
function Check-Completed([string]$Path,[int[]]$Exits=@(0)){
 $r=[IO.File]::ReadAllText($Path)|ConvertFrom-Json
 if($r.host.ToLowerInvariant() -ne 'baiying' -or $r.reason -ne 'completed' -or $r.exit_code -notin $Exits -or
    -not $r.host_checks_pass -or @($r.after_processes).Count -ne 0){throw ('Unqualified cleanup: '+$Path)}
 foreach($c in $r.host_checks.PSObject.Properties){if(-not $c.Value){throw 'Failed host check'}}
 return $r
}
function Run-Tool([string]$File,[string[]]$Arguments,[int]$Seconds){
 $info=[Diagnostics.ProcessStartInfo]::new();$info.FileName=$File
 $info.Arguments=(@($Arguments|ForEach-Object {'"'+([string]$_).Replace('"','\"')+'"'}) -join ' ')
 $info.UseShellExecute=$false;$info.CreateNoWindow=$true
 $info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true
 $p=[Diagnostics.Process]::new();$p.StartInfo=$info
 try{
  if(-not $p.Start()){throw 'Tool did not start'}
  $out=$p.StandardOutput.ReadToEndAsync();$err=$p.StandardError.ReadToEndAsync()
  if(-not $p.WaitForExit($Seconds*1000)){try{$p.Kill()}catch{};$null=$p.WaitForExit(5000);throw 'Tool timeout'}
  $p.WaitForExit();$stdout=$out.GetAwaiter().GetResult();$stderr=$err.GetAwaiter().GetResult()
  if($p.ExitCode -ne 0){throw ('Tool failed: '+$stderr)}
  return $stdout
 }finally{$p.Dispose()}
}
# Admission precedes archive extraction and every GPU operation.
$long=Check-Completed $m.active_long_record @(0,6)
if($long.spec.command_file_sha256 -ne $m.active_long_command_sha256 -or $long.spec.repo_commit -ne $m.active_long_repo_commit -or
   $long.spec.coarse_out_provider.commit -ne $m.runtime_source_commit){throw 'Long owner identity changed'}
Verify-File $PSCommandPath $m.script_sha256
Verify-File ('P:\projects\'+$m.worker) $m.worker_sha256
Verify-File $m.executable.path $m.executable.sha256
if((Run-Tool 'git.exe' @('-C',$m.repo,'rev-parse','HEAD') 30).Trim() -ne $m.runtime_source_commit){throw 'Runtime checkout changed'}
if((Run-Tool 'git.exe' @('-C',$m.probe_repo,'rev-parse','HEAD') 30).Trim() -ne $m.probe_source_commit){throw 'Probe checkout changed'}
foreach($item in $m.compilation_inputs.PSObject.Properties){
 Verify-File (Join-Path $m.repo $item.Name) $item.Value
 Verify-File (Join-Path $m.probe_repo $item.Name) $item.Value
}
foreach($item in $m.build_and_original_controls){Verify-File $item.path $item.sha256;$null=Check-Completed $item.path}
foreach($item in @($m.gate_tables)+@($m.shared_tables)){
 if((Get-Item -LiteralPath $item.path).Length -ne $item.bytes){throw ('Table extent: '+$item.path)}
 Verify-File $item.path $item.sha256
}
$archive='P:\projects\'+$m.archive
Verify-File $archive $m.archive_sha256
if(Test-Path $m.data){throw 'Input directory already exists'}
if(Test-Path $m.output){throw 'Output directory already exists'}
$drive=[IO.DriveInfo]::new('P:\')
if($drive.AvailableFreeSpace -lt 10GB+[long]$m.raw_input_bytes){throw 'Input extraction disk reserve'}
$members=@(((Run-Tool 'tar.exe' @('-tf',$archive) 60) -split "`r?`n")|Where-Object {$_.Length -gt 0})
if($members.Count -ne $m.files.Count){throw 'Archive membership extent'}
$expected=@($m.files|ForEach-Object {$_.member}|Sort-Object)
if(Compare-Object ($members|Sort-Object) $expected){throw 'Archive membership mismatch'}
$null=New-Item -ItemType Directory -Path $m.data
$null=Run-Tool 'tar.exe' @('-xf',$archive,'-C',$m.data) 60
foreach($item in $m.files){
 if((Get-Item -LiteralPath $item.path).Length -ne $item.bytes){throw ('Operand extent: '+$item.path)}
 Verify-File $item.path $item.sha256
}
$null=New-Item -ItemType Directory -Path $m.output
$spec=[ordered]@{
 executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 arguments=@('-NoProfile','-ExecutionPolicy','Bypass','-File',('P:\projects\'+$m.worker),'-SourcePath',$sourcePath,'-SourceSha256',(Get-FileHash $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant())
 working_directory=$m.repo;repo_commit=$m.runtime_source_commit
 probe_compilation_commit=$m.probe_source_commit;probe_executable=$m.executable
 command_file=$PSCommandPath;command_file_sha256=$m.script_sha256
 source_manifest_sha256=(Get-FileHash $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant()
 source_inputs=$m.compilation_inputs;input_archive_sha256=$m.archive_sha256
 input_file_count=$m.files.Count;cases=90;layouts=180
 model='D:\models\Qwen3.6-35B-A3B; independent GB10 operator operands, no model load'
 reference_host='gb10-4t';reference_capture_sha256=$m.reference_capture_sha256
 active_long_run_sha256=(Get-FileHash $m.active_long_record -Algorithm SHA256).Hash.ToLowerInvariant()
 model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false
}
$specPath=Join-Path $m.output 'spec.json'
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false))
$guard=Join-Path $m.repo 'scripts\baiying_guarded_inference.ps1'
Verify-File $guard $m.guard_sha256
& $guard -SpecPath $specPath -OutDir (Join-Path $m.output 'run') -TimeoutSeconds ([int]$m.native_timeout_seconds)|Out-Null
$run=Check-Completed (Join-Path $m.output 'run\run-record.json')
[ordered]@{reason=$run.reason;exit_code=$run.exit_code;wall_ms=$run.wall_ms;host_checks_pass=$run.host_checks_pass;model_loaded=$false}|ConvertTo-Json -Compress

