param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$SourceSha256)
$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
if((Get-FileHash -LiteralPath $SourcePath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $SourceSha256){throw 'Manifest changed'}
$m=[IO.File]::ReadAllText($SourcePath)|ConvertFrom-Json
if((Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $m.worker_sha256){throw 'Worker changed'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$completed=0
foreach($case in $m.cases){
 $arguments=@($case.paths)+@($case.gate_table)+@($m.shared_tables|ForEach-Object {$_.path})+@([string][int][bool]$case.packed_decode)
 if($arguments.Count -ne 13){throw 'Probe argument count'}
 if((Get-FileHash -LiteralPath $m.executable.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $m.executable.sha256){throw 'Probe changed'}
 $info=[Diagnostics.ProcessStartInfo]::new()
 $info.FileName=$m.executable.path
 $info.Arguments=(@($arguments|ForEach-Object {'"'+([string]$_).Replace('"','\"')+'"'}) -join ' ')
 $info.WorkingDirectory=$m.repo
 $info.UseShellExecute=$false;$info.CreateNoWindow=$true
 $info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true
 $process=[Diagnostics.Process]::new();$process.StartInfo=$info
 $clock=[Diagnostics.Stopwatch]::StartNew()
 try {
  if(-not $process.Start()){throw 'Probe did not start'}
  $stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync()
  if(-not $process.WaitForExit([int]$m.case_timeout_seconds*1000)){
   try{$process.Kill()}catch{}
   $null=$process.WaitForExit(5000)
   throw ('Probe timeout: '+$case.name)
  }
  $process.WaitForExit();$clock.Stop()
  $out=$stdout.GetAwaiter().GetResult();$err=$stderr.GetAwaiter().GetResult();$code=$process.ExitCode
  [IO.File]::WriteAllText((Join-Path $m.output ($case.name+'.stdout.jsonl')),$out,[Text.UTF8Encoding]::new($false))
  [IO.File]::WriteAllText((Join-Path $m.output ($case.name+'.stderr.log')),$err,[Text.UTF8Encoding]::new($false))
  $rows=@(($out -split "`r?`n")|Where-Object {$_.Length -gt 0}|ForEach-Object {$_|ConvertFrom-Json})
  [ordered]@{kind='step124_original_gdn_gpu_case';case=$case.name;position=$case.position;layer=$case.layer;input_token_id=$case.input_token_id;packed_decode=$case.packed_decode;executable_sha256=$m.executable.sha256;exit_code=$code;elapsed_ms=$clock.Elapsed.TotalMilliseconds;layouts=$rows}|ConvertTo-Json -Depth 10 -Compress
  if($code -ne 0 -or $rows.Count -ne 2){throw ('Probe failed: '+$case.name)}
  if(@($rows|Where-Object {$_.key_major}).Count -ne 1){throw 'Missing state layout'}
  foreach($row in $rows){
   if($row.kind -ne 'original_q1_recurrence_native_replay' -or $row.packed_decode -ne $case.packed_decode -or -not $row.passed -or
      $row.state_f32_bit_mismatches -ne 0 -or $row.core_bf16_mismatches -ne 0 -or $row.guard_mismatches -ne 0){throw 'Numerical comparison failed'}
  }
  ++$completed
 } finally {$process.Dispose()}
}
if($completed -ne 90){throw 'Incomplete case set'}
[ordered]@{kind='step124_original_gdn_gpu_complete';cases=$completed;layouts=$completed*2;model_loaded=$false;inference_acceptance=$false}|ConvertTo-Json -Compress
